head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > abort]<br/>현재 진행 중인 Submission 을 중지합니다.",
    "validation" : [
        "submissionId(필수) 파라미터로 중지할 Submission 의 ID 를 설정할 수 있어야 합니다.",
        "Submission 실행 중 비활성화(disabled) 된 컴포넌트들이 다시 활성화되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 시나리오/상태 캡처
scwin.currentScenario = null;
scwin.disabledSnapshot = null;



// submission 완료 콜백
scwin.sbm_basic_submitdone = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[submitdone] sbm_basic 완료 (abort 호출되지 않음) / 로드된 행 수 = " + dlt_userList.getRowCount());
};

scwin.sbm_basic_submiterror = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[submiterror] errorType=" + e.errorType + " (abort 로 중지된 경우 발생 가능)");
};



scwin.btn_runAbort_onclick = function () {
    var scenario = par_scenario.getValue();
    scwin.currentScenario = scenario;
    scwin.disabledSnapshot = null;

    // 매 시나리오 실행 시 이전 데이터/상태 제거
    dlt_userList.removeAll();
    btn_target1.setDisabled(false);
    btn_target2.setDisabled(false);
    ibx_target1.setDisabled(false);

    if (scenario === "1") {
        // 시나리오 1 : submission 실행 → 즉시 abort - submissionId 만 전달
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : executeSubmission 실행 → 즉시 WebSquare.ModelUtil.abort('sbm_basic') 호출 ──");
        WebSquare.ModelUtil.executeSubmission("sbm_basic", null, [btn_target1, btn_target2, ibx_target1]);

        // 호출 직후 disabled 캡처 (실행 중)
        scwin.disabledSnapshot = {
            before : [btn_target1.getDisabled(), btn_target2.getDisabled(), ibx_target1.getDisabled()]
        };
        wf_body_bottom.getObj("scwin").setReturnValue("실행 직후 disabled 상태 : [" + scwin.disabledSnapshot.before.join(",") + "]");

        // abort 호출 → 가이드 @spec : 비활성화된 컴포넌트들이 다시 활성화됨
        WebSquare.ModelUtil.abort("sbm_basic");

        // abort 직후 disabled 상태
        var afterAbort = [btn_target1.getDisabled(), btn_target2.getDisabled(), ibx_target1.getDisabled()];
        wf_body_bottom.getObj("scwin").setReturnValue("abort 직후 disabled 상태 : [" + afterAbort.join(",") + "] (모두 false 면 재활성화 PASS)");
    } else if (scenario === "2") {
        // 시나리오 2 : 진행 중 submission 이 없을 때 abort - 에러 없이 처리되어야 함
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 진행 중 submission 없을 때 WebSquare.ModelUtil.abort('sbm_basic') 호출 ──");
        try {
            var ret = WebSquare.ModelUtil.abort("sbm_basic");
            wf_body_bottom.getObj("scwin").setReturnValue("abort 호출 완료 (반환값 : " + ret + ") - 진행 중 submission 없음");
        } catch (ex) {
            wf_body_bottom.getObj("scwin").setReturnValue("abort 예외 발생 : " + ex.message);
        }
    }
};
